import SideBar from "@components/layout/sidebar";
import SideBarSmall from "@components/layout/sidebar-small";
import { useAppContext } from "@providers/AppContext";
import { useTheme } from "@providers/ThemeProvider";
export default function ChatLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    const { sidebarExpanded } = useAppContext();
    const { theme } = useTheme();
    const darkTheme = theme === "dark";

    return <div className="flex h-full w-full">
        <aside
            className={`shrink-0 transition-all duration-750 ease-in-out 
                max-[910px]:bg-dark-shade-1 max-[910px]:absolute 
                max-[910px]:w-full max-[910px]:min-w-[380px]
            `}
            style={{
                width: sidebarExpanded ? "260px" : "60px",
            }}
        >
            <div
                className={`relative h-full transition-all duration-750 ease-in-out overflow-hidden z-[100]`}
                style={{
                    width: sidebarExpanded ? "260px" : "60px",
                    opacity: sidebarExpanded ? 1 : 0,
                    backgroundColor: darkTheme
                        ? "var(--theme-dark-black-secondary)"
                        : "var(--theme-light-white-secondary)",
                }}
            >
                <SideBar />
            </div>
            <div
                className="max-w-[60px] h-full overflow-hidden absolute"
                style={{ left: 0, top: 0 }}
            >
                <SideBarSmall />
            </div>
        </aside>
        <section className="flex flex-col h-full transition-all duration-750 ease-in-out border-l border-solid border-gray-dark">
            {children}
        </section>
    </div>;
}